theorem poissonInverse_joint_smooth_on_open_slab (f : Pressure) {I : Set ℝ}
    (hI : IsOpen I)
    (hf : ContDiffOn ℝ ∞ (fun z : ℝ × Vec => f z.1 z.2) {z | z.1 ∈ I})
    (hp : ∀ s ∈ I, SpatialPeriodic (f s)) :
    ContDiffOn ℝ ∞ (fun z : ℝ × Vec => poissonInverse (f z.1) z.2)
      {z | z.1 ∈ I}

theorem lorentzian_of_gaussianGluingLaw
    {K : BoundaryTensor} {t0 δ : ℝ} {f : GaussianJoint → BulkMatrix} {z : GaussianJoint}
    (hf : GaussianGluingLaw K t0 δ f z) : LorentzianAt (metricOfJoint f) (bulkFromJoint z)

theorem scalarCompletionUpper_conserved {ψ : Pressure} {t : ℝ} {x : Vec}
    (hψ : AnalyticAt ℝ (fun z : ℝ × Vec => ψ z.1 z.2) (t, x)) :
    ∀ b, upperDivergence (scalarCompletionUpper ψ) t x b = 0

theorem completedBoundary_symmetric {ν ρ : ℝ} {u : Velocity} {p ψ : Pressure}
    {t : ℝ} {x : Vec}
    (hψ : AnalyticAt ℝ (fun z : ℝ × Vec => ψ z.1 z.2) (t,x)) :
    (completedBoundary ν ρ u p ψ t x).IsSymm

theorem gaussianVacuum_boundary_hamiltonian {ρ t0 δ ε : ℝ} {g : Metric}
    (hg : GaussianVacuum ρ t0 δ ε g) {t : ℝ} (ht : t ∈ timeInterval t0 δ) (x : Vec) :
    boundaryHamiltonian (boundaryK g) t x = 0

theorem gaussianVacuum_boundary_codazzi {ρ t0 δ ε : ℝ} {g : Metric}
    (hg : GaussianVacuum ρ t0 δ ε g) {t : ℝ} (ht : t ∈ timeInterval t0 δ)
    (x : Vec) (a : Fin 4) : boundaryCodazzi (boundaryK g) t x a = 0

theorem gaussianVacuum_boundaryAdmissible {ρ t0 δ ε : ℝ} {g : Metric}
    (hg : GaussianVacuum ρ t0 δ ε g) :
    BoundaryAdmissible ρ t0 δ (boundaryK g)

theorem boundaryAdmissible_beta_mean {ρ t0 δ : ℝ} {K : BoundaryTensor}
    (hK : BoundaryAdmissible ρ t0 δ K) {t : ℝ} (ht : t ∈ timeInterval t0 δ) :
    scalarMean (boundaryBeta K t) = ρ

theorem boundaryAdmissible_solenoidal {ρ t0 δ : ℝ} {K : BoundaryTensor}
    (hK : BoundaryAdmissible ρ t0 δ K) {t : ℝ} (ht : t ∈ timeInterval t0 δ)
    (x : Vec) : divergence (boundaryVelocity K t) x = 0

theorem boundaryAdmissible_potential_eq {ρ t0 δ : ℝ} {K : BoundaryTensor}
    (hK : BoundaryAdmissible ρ t0 δ K) {t : ℝ} (ht : t ∈ timeInterval t0 δ) :
    boundaryPotential K t = poissonInverse (fun x => boundaryBeta K t x - ρ)

theorem boundaryAdmissible_potential_laplacian {ρ t0 δ : ℝ} {K : BoundaryTensor}
    (hK : BoundaryAdmissible ρ t0 δ K) {t : ℝ} (ht : t ∈ timeInterval t0 δ)
    (x : Vec) : scalarLaplacian (boundaryPotential K t) x = boundaryBeta K t x - ρ

theorem boundaryAdmissible_potential_time_initial {ρ t0 δ : ℝ} {K : BoundaryTensor}
    (hK : BoundaryAdmissible ρ t0 δ K) :
    ∀ x, scalarLocalTimeDerivative (boundaryPotential K) t0 x = 0

theorem boundaryAdmissible_decoded_pair {ρ t0 δ : ℝ} {K : BoundaryTensor}
    (hK : BoundaryAdmissible ρ t0 δ K) :
    AnalyticPeriodicPair t0 δ (boundaryVelocity K) (boundaryPressure ρ K)

theorem completedBoundary_pressure_gauge {ν ρ t : ℝ} {u : Velocity}
    {p ψ : Pressure} {a γ : ℝ → ℝ} {x : Vec}
    (hψ : AnalyticAt ℝ (fun z : ℝ × Vec => ψ z.1 z.2) (t, x))
    (ha : AnalyticAt ℝ a t) (ha2 : deriv (deriv a) t = γ t) :
    completedBoundary ν ρ u (fun s y => p s y + γ s)
      (fun s y => ψ s y - a s) t x = completedBoundary ν ρ u p ψ t x
